mapper.select:
SELECT DISTINCT ip.product_id, ip.warehouse_id, ip.supplier_id, ip.plan_quantity, ip.univalence, ip.discount, ip.money, ip.create_by, ip.create_time, ip.update_by, ip.update_time, p.product_code, p.product_name, p.product_type, p.product_specifications, p.measure_unit, p.producer, pt.product_type_id, pt.parent_id, pt.ancestors, pt.product_type_name, w.warehouse_name FROM inventory_product ip JOIN product p ON ip.product_id = p.product_id JOIN warehouse w ON w.warehouse_id = ip.warehouse_id JOIN product_type pt ON pt.product_type_id = p.product_type where 1=1
AND p.product_id = #{productId}
AND p.product_code like concat('%', #{productCode}, '%')
AND p.product_name like concat('%', #{productName}, '%')
AND p.product_type = #{productType}
AND p.product_specifications = #{productSpecifications}
AND ip.warehouse_id = #{warehouseId}

SELECT DISTINCT
ip.product_id, ip.warehouse_id, ip.supplier_id, ip.plan_quantity,
ip.univalence, ip.discount, ip.money, ip.create_by, ip.create_time, ip.update_by, ip.update_time,
p.product_code, p.product_name, p.product_type, p.product_specifications, p.measure_unit, p.producer,
pt.product_type_id, pt.parent_id, pt.ancestors, pt.product_type_name, w.warehouse_name
FROM inventory_product ip
JOIN product p ON ip.product_id = p.product_id
JOIN warehouse w ON w.warehouse_id = ip.warehouse_id
JOIN product_type pt ON pt.product_type_id = p.product_type
join detail_receipt d ON p.product_id = d.product_id
join head_receipt h ON h.systematic_receipt = d.systematic_receipt
where 1=1

    AND p.product_code like concat('%', #{productCode}, '%')


    AND p.product_name like concat('%', #{productName}, '%')


    AND p.product_type = #{productType}


    AND p.product_specifications = #{productSpecifications}


    AND ip.warehouse_id = #{warehouseId}


    and not exists (select 1 from head_receipt h2 where h2.systematic_receipt = h.systematic_receipt
    and h2.invoice_date >= #{invoiceDate}
    )


    and exists (select 1 from head_receipt h2 where h2.systematic_receipt = h.systematic_receipt
    and h2.invoice_date < #{invoiceDate}
    )


where ip.product_id = #{productId}
and ip.warehouse_id in (#{warehousingId}, #{retrievalId})
limit 1
